// Written by Android/scripts/export-patterns.sh from the iOS demo. Don't edit by hand.

package dev.codepassion.hapticengine.demo

/**
 * The categories the demo groups patterns under, as in the iOS demo: the seven groups of patterns built
 * by hand, then the families. The name is saved, so renaming one forgets a saved filter for it.
 */
enum class PatternCategory(val title: String, val symbol: String, val tint: DemoTint, val group: CategoryGroup) {
    Feedback("Feedback", "hand.tap", DemoTint.Teal, CategoryGroup.BuiltIn),
    Alerts("Alerts", "bell", DemoTint.Orange, CategoryGroup.BuiltIn),
    Rhythm("Rhythm", "metronome", DemoTint.Pink, CategoryGroup.BuiltIn),
    Texture("Texture", "waveform", DemoTint.Purple, CategoryGroup.BuiltIn),
    Nature("Nature", "leaf", DemoTint.Green, CategoryGroup.BuiltIn),
    Mechanical("Mechanical", "gearshape", DemoTint.Gray, CategoryGroup.BuiltIn),
    Game("Game", "gamecontroller", DemoTint.Indigo, CategoryGroup.BuiltIn),
    Impacts("Impacts", "hammer", DemoTint.Brown, CategoryGroup.Families),
    TapCounts("Tap Counts", "number", DemoTint.Blue, CategoryGroup.Families),
    Signals("Signals", "antenna.radiowaves.left.and.right", DemoTint.Red, CategoryGroup.Families),
    Meters("Meters", "music.note", DemoTint.Mint, CategoryGroup.Families),
    Surfaces("Surfaces", "hand.draw", DemoTint.Orange, CategoryGroup.Families),
    Waves("Waves", "waveform.path", DemoTint.Cyan, CategoryGroup.Families),
    Dynamics("Dynamics", "chart.line.uptrend.xyaxis", DemoTint.Purple, CategoryGroup.Families),
    Weather("Weather", "cloud.sun", DemoTint.Green, CategoryGroup.Families),
    Machines("Machines", "wrench.and.screwdriver", DemoTint.Gray, CategoryGroup.Families),
    Arcade("Arcade", "arcade.stick", DemoTint.Indigo, CategoryGroup.Families),
    Animals("Animals", "pawprint", DemoTint.Brown, CategoryGroup.Families),
    Emotions("Emotions", "face.smiling", DemoTint.Pink, CategoryGroup.Families),
    Sports("Sports", "sportscourt", DemoTint.Green, CategoryGroup.Families),
    Instruments("Instruments", "pianokeys", DemoTint.Purple, CategoryGroup.Families),
    Vehicles("Vehicles", "car", DemoTint.Blue, CategoryGroup.Families),
    Controls("Controls", "switch.2", DemoTint.Teal, CategoryGroup.Families),
    Body("Body", "figure.stand", DemoTint.Orange, CategoryGroup.Families),
    Kitchen("Kitchen", "fork.knife", DemoTint.Red, CategoryGroup.Families),
    Tools("Tools", "hammer", DemoTint.Gray, CategoryGroup.Families),
